// Get current environment from env var or default to 'local'
const env = $env.NODE_ENV || 'local';
const timestamp = new Date().toISOString();

return {
  env,
  timestamp,
  collection_id: $json.id || $now.toISOString()
};

// Aggregate all the query results into a single snapshot
const env = $('Setup Environment').first().json.env;
const timestamp = $('Setup Environment').first().json.timestamp;

const staleWorkflows = $('Query Stale Workflows').first().json.rows[0]?.count || 0;
const credentialIssues = $('Query Credential Issues').first().json.rows[0]?.count || 0;
const deadletters = $('Query Dead Letters').first().json.rows[0]?.count || 0;
const jobsBloat = $('Query Jobs Bloat').first().json.rows[0] || { old_jobs: 0, old_results: 0 };
const staleInvoices = $('Query Stale Invoices').first().json.rows[0]?.count || 0;
const memoryBloat = $('Query Memory Bloat').first().json.rows[0]?.count || 0;

// Calculate depreciation score (0-100)
let score = 0;
if (staleWorkflows > 10) score += 25;
else if (staleWorkflows > 5) score += 15;
else if (staleWorkflows > 0) score += 5;

if (credentialIssues > 5) score += 25;
else if (credentialIssues > 2) score += 15;
else if (credentialIssues > 0) score += 10;

if (deadletters > 100) score += 25;
else if (deadletters > 50) score += 15;
else if (deadletters > 10) score += 10;

if (jobsBloat.old_jobs > 1000) score += 15;
else if (jobsBloat.old_jobs > 500) score += 10;
else if (jobsBloat.old_jobs > 100) score += 5;

if (memoryBloat > 1000) score += 10;
else if (memoryBloat > 500) score += 5;

return {
  env,
  timestamp,
  snapshot: {
    stale_workflows: staleWorkflows,
    credential_issues: credentialIssues,
    deadletters: deadletters,
    jobs_old: jobsBloat.old_jobs,
    results_old: jobsBloat.old_results,
    invoices_stale: staleInvoices,
    memory_bloat: memoryBloat
  },
  depreciation_score: score,
  severity: score > 50 ? 'critical' : score > 25 ? 'warning' : 'ok'
};

// Prepare Slack alert message
const env = $json.env;
const score = $json.depreciation_score;
const severity = $json.severity;
const snapshot = $json.snapshot;

let emoji = '✅';
let color = 'good';
if (severity === 'critical') {
  emoji = '🚨';
  color = 'danger';
} else if (severity === 'warning') {
  emoji = '⚠️';
  color = 'warning';
}

const message = {
  attachments: [{
    color: color,
    title: `${emoji} Depreciation Radar - ${env.toUpperCase()}`,
    text: `Score: ${score}/100 (${severity})`,
    fields: [
      {
        title: 'Stale Workflows',
        value: snapshot.stale_workflows,
        short: true
      },
      {
        title: 'Credential Issues',
        value: snapshot.credential_issues,
        short: true
      },
      {
        title: 'Dead Letters',
        value: snapshot.deadletters,
        short: true
      },
      {
        title: 'Old Jobs',
        value: snapshot.jobs_old,
        short: true
      },
      {
        title: 'Stale Invoices',
        value: snapshot.invoices_stale,
        short: true
      },
      {
        title: 'Memory Bloat',
        value: snapshot.memory_bloat,
        short: true
      }
    ],
    footer: `Collected at ${new Date().toISOString()}`
  }]
};

return message;

// Final summary for logs
const env = $json.env;
const score = $json.depreciation_score;
const severity = $json.severity;
const snapshot = $json.snapshot;

console.log(`🚀 Radar Collection Complete for ${env}`);
console.log(`📊 Depreciation Score: ${score}/100 (${severity})`);
console.log(`📈 Metrics:`, JSON.stringify(snapshot, null, 2));

return {
  success: true,
  env,
  score,
  severity,
  timestamp: new Date().toISOString()
};
